class ImageGenTool(BaseAPITypeExtra):
    """A tool that generates images using the GPT image models.

    Attributes:
        type: The type of the image generation tool. Always
            `image_generation`.
        complexity: Computation spent planning the image,
            independently of rendering quality. Overrides the outer
            response's `reasoning.effort` for image generation. When
            omitted, inherits a supported outer reasoning effort or
            uses the image model's configured default. For SVG
            output, controls the reference image, not the SVG
            author's reasoning.
        quality: The quality of the generated image. The GPT image
            models support `low`, `medium`, and `high`.
            `gpt-image-2.5-sunburst` and `gpt-image-2.5-flare`,
            including their `2026-09-08` snapshots, also support
            `xhigh` and `max`. Default: `auto`.
        size: The size of the generated images. For `gpt-image-2`,
            `gpt-image-2-2026-04-21`, `gpt-image-2.5-sunburst`,
            `gpt-image-2.5-sunburst-2026-09-08`,
            `gpt-image-2.5-flare`, and
            `gpt-image-2.5-flare-2026-09-08`, arbitrary resolutions
            are supported as `WIDTHxHEIGHT` strings, for example
            `1536x864`. Width and height must both be divisible by 16
            and the requested aspect ratio must be between 1:3 and
            3:1. Resolutions above `2560x1440` are experimental, and
            the maximum supported resolution is `3840x2160`. The
            requested size must also satisfy the model's current
            pixel and edge limits. The standard sizes `1024x1024`,
            `1536x1024`, and `1024x1536` are supported by the GPT
            image models; `auto` is supported for models that allow
            automatic sizing.
        output_format: The output format of the generated image. One
            of `png`, `webp`, `jpeg`, `gif`, or `svg`. Default:
            `png`. GIF and SVG output require a model that supports
            the selected format. GIF output does not support partial
            image streaming (`partial_images` greater than `0`),
            `input_image_mask`, or custom `output_compression`.
            Responses lifecycle events can still be streamed for GIF
            output.
        frame_count: Number of GIF frames. Requires `output_format`
            to be `gif`. Default: 9.
        frame_duration_ms: Duration of each GIF frame in
            milliseconds, rounded to 10 ms. Requires `output_format`
            to be `gif`. Default: 200.
        svg: SVG author model settings. Requires `output_format` to
            be `svg`. When SVG model selection is enabled, omitting
            this object uses the outer response model. Otherwise, the
            default SVG author is used and explicit model overrides
            are unavailable.
        output_compression: Compression level for the output image.
            Default: 100.
        moderation: Moderation level for the generated image.
            Default: `auto`.
        background: Set the background of the generated image. One of
            `transparent`, `opaque`, or `auto`.
            `gpt-image-2.5-sunburst` and `gpt-image-2.5-flare`,
            including their `2026-09-08` snapshots, support `opaque`
            and `transparent` backgrounds. Transparent backgrounds
            are available for supported GPT Image models. For
            `gpt-image-2` and `gpt-image-2-2026-04-21`, this support
            is in preview. When using `transparent`, set the output
            format to `png` or `webp`. Default: `auto`.
        input_fidelity: Control how much effort the model will exert
            to match the style and features, especially facial
            features, of input images. Supports `high` and `low` on
            `gpt-image-1.5`; `gpt-image-1-mini` supports only `low`.
            For `gpt-image-2`, omit this parameter. Defaults to `low`
            on supported models.
        input_image_mask: Optional mask for inpainting. Contains
            `image_url` (string, optional) and `file_id` (string,
            optional).
        partial_images: Number of partial images to generate in
            streaming mode, from 0 (default value) to 3.
        action: Whether to generate a new image or edit an existing
            image. Default: `auto`.
    """

    __upstream_schema__ = "ImageGenTool"
